// Helper function to calculate the sum of ASCII values of uppercase characters
function SumUpperCaseASCII(s: string): int
    requires s != null
    ensures result >= 0
{
    var sum := 0;
    var i := 0;
    while i < s.Length
        invariant 0 <= i <= s.Length
        invariant sum == SumUpperCaseASCII(s.Substring(0, i))
    {
        if s[i] >= 'A' && s[i] <= 'Z' {
            sum := sum + (ord(s[i]));
        }
        i := i + 1;
    }
    sum
}
